-- Item mall catalog of the client's Cash.SData (61 products), upserted into
-- PS_GameDefs.dbo.ProductList so the codes the client sends in 0x2602/0x2603
-- exist on the server (the stock EP4.5 rows use other codes and are kept).
-- Apply: python3 tools/sqlserver.py query --database PS_GameDefs --file tools/sql/client_cash_catalog.sql
-- Regenerate after editing Cash.SData (dump it with Parsec: ProductCode, Cost, ProductName, Items).
SET NOCOUNT ON; SET XACT_ABORT ON; BEGIN TRAN;
DELETE FROM dbo.ProductList WHERE ProductCode IN ('Basicos_1','Basicos_2','Basicos_4','Basicos_5','Basicos_6','Basicos_7','Basicos_8','Basicos_9','Especial_1','Basicos_10','Alas_1','Items_1','Basicos_11','Basicos_12','Basicos_13','Basicos_14','Items_2','Items_3','Items_4','Items_5','Items_6','Items_7','Items_8','Items_9','Items_11','Items_12','Items_13','Items_14','Items_15','Items_16','Items_17','Items_18','Items_19','Items_20','Items_21','Items_22','Items_23','Items_24','Items_25','Items_26','Items_27','Items_28','Items_29','Items_30','Items_31','Items_32','Items_33','Items_34','Items_35','Items_36','Items_37','AP_1','AP_2','AP_3','AP_4','AP_6','Summon_1','Hammers_1','Runes_1','Runes_2','Runes_3');
DECLARE @base int = (SELECT ISNULL(MAX(RowID),0) FROM dbo.ProductList);
COMMIT; SELECT COUNT(*) FROM dbo.ProductList;
